func maybePromptVercelDeploymentDisable(ctx context.Context, w io.Writer, promptFn func() (bool, error)) (bool, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return false, nil
	}

	vercelJSONPath := filepath.Join(repoRoot, "vercel.json")
	hasVercelJSON := false
	if _, err := os.Stat(vercelJSONPath); err == nil {
		hasVercelJSON = true
	} else if !os.IsNotExist(err) {
		fmt.Fprintf(w, "Note: Skipping Vercel deployment update: could not check vercel.json: %v\n", err)
		return false, nil
	}

	hasVercelProject := hasVercelJSON
	if !hasVercelProject {
		for _, path := range []string{
			filepath.Join(repoRoot, ".vercel"),
			filepath.Join(repoRoot, "vercel.ts"),
		} {
			if _, err := os.Stat(path); err == nil {
				hasVercelProject = true
				break
			} else if !os.IsNotExist(err) {
				fmt.Fprintf(w, "Note: Skipping Vercel deployment update: could not check %s: %v\n", path, err)
				return false, nil
			}
		}
	}

	if !hasVercelProject {
		return false, nil
	}

	projectSettingsPath := filepath.Join(repoRoot, settings.EntireSettingsFile)
	projectSettings, err := settings.LoadFromFile(projectSettingsPath)
	if err != nil {
		return false, fmt.Errorf("load project settings: %w", err)
	}
	if projectSettings.Vercel {
		return false, nil
	}

	if config, alreadyDisabled, loadErr := vercelconfig.Load(vercelJSONPath, hasVercelJSON); loadErr == nil &&
		config != nil && alreadyDisabled {
		projectSettings.Vercel = true
		if err := settings.Save(ctx, projectSettings); err != nil {
			return false, fmt.Errorf("save project settings: %w", err)
		}
		fmt.Fprintf(w, "✓ Updated %s to manage Vercel deployment blocking on `%s`\n", configDisplayProject, vercelconfig.BranchPattern)
		return true, nil
	}

	if promptFn == nil {
		if !canPromptInteractively() {
			fmt.Fprintf(w, "Note: Vercel detected. Run `entire configure` interactively to disable deployments for `%s` branches.\n", vercelconfig.BranchPattern)
			return false, nil
		}
		promptFn = promptVercelDeploymentDisable
	}

	disableDeployments, err := promptFn()
	if err != nil {
		return false, fmt.Errorf("vercel prompt: %w", err)
	}
	if !disableDeployments {
		return false, nil
	}

	projectSettings.Vercel = true
	if err := settings.Save(ctx, projectSettings); err != nil {
		return false, fmt.Errorf("save project settings: %w", err)
	}

	fmt.Fprintf(w, "✓ Updated %s to manage Vercel deployment blocking on `%s`\n", configDisplayProject, vercelconfig.BranchPattern)
	return true, nil
}

func promptVercelDeploymentDisable() (bool, error) {
	disableDeployments := true
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Disable Vercel deployments for Entire branches?").
				Description("Prevent preview deployments for `entire/**` branches by writing to the metadata branch vercel.json.").
				Affirmative("Yes").
				Negative("No").
				Value(&disableDeployments),
		),
	)

	if err := form.Run(); err != nil {
		return false, err
	}

	return disableDeployments, nil
}

// runUninstall completely removes Entire from the repository.
func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
	// Check if we're in a git repository
	if _, err := paths.WorktreeRoot(ctx); err != nil {
		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")

	emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return err
	}
	emptyTreeHash, err = s.maybeMergeVercelConfig(ctx, emptyTreeHash)
	if err != nil {
		return err
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
	if err != nil {
		return err
	}

	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}
	return nil
}

func (s *GitStore) maybeMergeVercelConfig(ctx context.Context, rootTreeHash plumbing.Hash) (plumbing.Hash, error) {
	repoRoot, err := repositoryRoot(s.repo)
	if err != nil {
		return rootTreeHash, nil
	}

	projectSettings, err := settings.LoadFromRepoRoot(repoRoot)
	if err != nil || !projectSettings.Vercel {
		return rootTreeHash, nil
	}

	config := make(map[string]any)
	var existingContents string
	if rootTreeHash != plumbing.ZeroHash {
		tree, treeErr := s.repo.TreeObject(rootTreeHash)
		if treeErr != nil && !errors.Is(treeErr, plumbing.ErrObjectNotFound) {
			return plumbing.ZeroHash, fmt.Errorf("read metadata tree: %w", treeErr)
		}
		if treeErr == nil {
			file, fileErr := tree.File(vercelconfig.FileName)
			if fileErr == nil {
				contents, contentsErr := file.Contents()
				if contentsErr != nil {
					return plumbing.ZeroHash, fmt.Errorf("read %s from metadata branch: %w", vercelconfig.FileName, contentsErr)
				}
				existingContents = contents
				if unmarshalErr := json.Unmarshal([]byte(contents), &config); unmarshalErr != nil {
					config = make(map[string]any)
				}
			}
		}
	}

	vercelconfig.MergeDeploymentDisabled(config)
	output, err := vercelconfig.Marshal(config)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	if string(output) == existingContents {
